import React from 'react';
import { Send, Paperclip, Image } from 'lucide-react';
import './Dashboard.css';
import Navbar from '../Components/Navbar';
import Sidebar from '../Components/Sidebar';
import dashboardArrow from '../assets/dashboaredarrow.svg';
import gridIcon from '../assets/Grid.svg';
import microphoneIcon from '../assets/Microphone.svg';
import apitestingIcon from '../assets/apitestingicons.svg';
import guitestingIcon from '../assets/guitestingagent.svg';

const Dashboard = () => {
  const features = {
    'API Testing Agent': [
      'Generate the test cases for on-boarding flow',
      'Generate and run the test cases from the given swagger file',
      'Generate and run the test cases from the given swagger file'
    ],
    'GUI Testing Agent': [
      'Generate and run the test cases from the given swagger file',
      'Generate and run the test cases from the given swagger file',
      'Generate and run the test cases from the given swagger file'
    ]
  };

  return (
    <div className="dashboard-container">
      <Navbar />
      <div className="main-content">
        <Sidebar />
        <div className="dashboard-content">
          <div className="agent-cards-container">
            {/* API Testing Agent Card */}
            <div className="agent-card api-card">
              <div className="agent-header">
                <img src={apitestingIcon} alt="API Testing" className="agent-icon" />
                <h2>API Testing Agent</h2>
              </div>
              <div className="agent-features">
                {features['API Testing Agent'].map((item, index) => (
                  <div className="feature-item" key={index}>
                    <span>{item}</span>
                    <img src={dashboardArrow} alt="arrow" />
                  </div>
                ))}
              </div>
            </div>

            {/* GUI Testing Agent Card */}
            <div className="agent-card gui-card">
              <div className="agent-header">
                <img src={guitestingIcon} alt="GUI Testing" className="agent-icon" />
                <h2>GUI Testing Agent</h2>
              </div>
              <div className="agent-features">
                {features['GUI Testing Agent'].map((item, index) => (
                  <div className="feature-item" key={index}>
                    <span>{item}</span>
                    <img src={dashboardArrow} alt="arrow" />
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
